INSERT INTO clues (dish_id, order_index, text) VALUES
((SELECT id FROM dishes WHERE slug='tibs'), 1, 'Sizzling meat eaten with your right hand and torn pieces of spongy bread.'),
((SELECT id FROM dishes WHERE slug='tibs'), 2, 'An 18th-century visitor wrote that hosts served it to pay a particular compliment to a guest.'),
((SELECT id FROM dishes WHERE slug='tibs'), 3, 'Families still cook it to mark holidays and special events, and the heat runs from mild to fierce.'),
((SELECT id FROM dishes WHERE slug='tibs'), 4, 'You sauté cubes of beef with onion, tomato and chili in spiced clarified butter until they sizzle.'),
((SELECT id FROM dishes WHERE slug='tibs'), 5, 'Sizzling sautéed beef scooped up with torn injera in Ethiopia.'),
((SELECT id FROM dishes WHERE slug='misir-wot'), 1, 'A brick-red puddle ladled onto a wide sour pancake beside other stews.'),
((SELECT id FROM dishes WHERE slug='misir-wot'), 2, 'Orthodox Christians eat it through the long fasting periods, when meat and dairy are off the table.'),
((SELECT id FROM dishes WHERE slug='misir-wot'), 3, 'Cooks start it the way stews of its kind begin, with onions softened in a dry pot before any fat.'),
((SELECT id FROM dishes WHERE slug='misir-wot'), 4, 'You stew split red lentils with onion, garlic and a hot spice blend called berbere until they collapse.'),
((SELECT id FROM dishes WHERE slug='misir-wot'), 5, 'Ethiopia''s spicy red lentil stew, soft and brick-coloured, served on injera.'),
((SELECT id FROM dishes WHERE slug='pastilla'), 1, 'A round pie dusted with sugar and cinnamon, though the filling is meat.'),
((SELECT id FROM dishes WHERE slug='pastilla'), 2, 'Historians trace it to Andalusi cookbooks, while others credit Algerian migrants or Sephardic Jews.'),
((SELECT id FROM dishes WHERE slug='pastilla'), 3, 'The classic filling is young pigeon, though most cooks now use shredded chicken.'),
((SELECT id FROM dishes WHERE slug='pastilla'), 4, 'You layer spiced shredded chicken, egg custard and sugared almonds between sheets of paper-thin pastry and bake it.'),
((SELECT id FROM dishes WHERE slug='pastilla'), 5, 'Morocco''s sweet-and-savory poultry pie, flaky under powdered sugar and cinnamon, served at feasts.'),
((SELECT id FROM dishes WHERE slug='harira'), 1, 'The bowl that breaks the fast at sunset, set out beside dates.'),
((SELECT id FROM dishes WHERE slug='harira'), 2, 'Food historian Gil Marks credits Morocco, though western Algeria has deep roots in it too.'),
((SELECT id FROM dishes WHERE slug='harira'), 3, 'Just before serving, the cook whisks in tadouira, a flour-and-water paste that thickens it to velvet.'),
((SELECT id FROM dishes WHERE slug='harira'), 4, 'You simmer lamb with tomatoes, lentils, chickpeas, cinnamon and ginger, and finish with handfuls of cilantro.'),
((SELECT id FROM dishes WHERE slug='harira'), 5, 'Tomato, lentil and chickpea soup eaten with dates and boiled eggs to end the fast in Morocco.'),
((SELECT id FROM dishes WHERE slug='chicken-yassa'), 1, 'A heap of soft golden onions that almost hides the meat underneath.'),
((SELECT id FROM dishes WHERE slug='chicken-yassa'), 2, 'Cooks in Casamance, down south, are known for the chicken version, and it spread across West Africa.'),
((SELECT id FROM dishes WHERE slug='chicken-yassa'), 3, 'The marinade does double duty: the citrus and mustard soak the chicken overnight, then become the sauce.'),
((SELECT id FROM dishes WHERE slug='chicken-yassa'), 4, 'You marinate chicken in lemon, mustard and garlic, brown it, then simmer it in the onions you cooked down.'),
((SELECT id FROM dishes WHERE slug='chicken-yassa'), 5, 'Senegal''s lemony chicken smothered in caramelized onions, spooned over white rice.'),
((SELECT id FROM dishes WHERE slug='puff-puff'), 1, 'Golden dough balls scooped hot from the oil into a paper bag.'),
((SELECT id FROM dishes WHERE slug='puff-puff'), 2, 'Nigeria gave it its English name, and Ghana, Congo and Cameroon each call it something else.'),
((SELECT id FROM dishes WHERE slug='puff-puff'), 3, 'Cooks drop the batter from a clenched fist, squeezing out one round blob at a time.'),
((SELECT id FROM dishes WHERE slug='puff-puff'), 4, 'You let a yeasted batter of flour, sugar and nutmeg rise until bubbly, then fry spoonfuls until golden.'),
((SELECT id FROM dishes WHERE slug='puff-puff'), 5, 'Sweet fried dough balls, chewy inside and sometimes rolled in sugar, as Nigeria makes them.'),
((SELECT id FROM dishes WHERE slug='anzac-biscuits'), 1, 'Chewy oat rounds sold to raise money for veterans each April.'),
((SELECT id FROM dishes WHERE slug='anzac-biscuits'), 2, 'Wives and women''s groups are thought to have posted them to soldiers abroad because they kept well.'),
((SELECT id FROM dishes WHERE slug='anzac-biscuits'), 3, 'Australian law bans the war''s name on goods, except on these, and only if they are never called cookies.'),
((SELECT id FROM dishes WHERE slug='anzac-biscuits'), 4, 'You melt butter with golden syrup, stir in baking soda till it foams, and mix it into oats, flour and coconut.'),
((SELECT id FROM dishes WHERE slug='anzac-biscuits'), 5, 'Australia''s eggless oat cookie, golden and chewy, though New Zealand claims it too.'),
((SELECT id FROM dishes WHERE slug='chimichanga'), 1, 'A fat rectangular parcel, deep-fried until blistered.'),
((SELECT id FROM dishes WHERE slug='chimichanga'), 2, 'A Tucson restaurant says its founder dropped one in the fryer by accident; a Phoenix chain says 1946.'),
((SELECT id FROM dishes WHERE slug='chimichanga'), 3, 'Legend says the cook bit back a Spanish curse mid-word and blurted out the dish''s name instead.'),
((SELECT id FROM dishes WHERE slug='chimichanga'), 4, 'You fold beef, beans, rice and cheese into a flour tortilla, seal it into a packet, and deep-fry it.'),
((SELECT id FROM dishes WHERE slug='chimichanga'), 5, 'Arizona''s deep-fried burrito, a Mexican American invention under guacamole and sour cream.'),
((SELECT id FROM dishes WHERE slug='queso-dip'), 1, 'Molten orange in a little bowl that costs extra, unlike the salsa.'),
((SELECT id FROM dishes WHERE slug='queso-dip'), 2, 'It likely descends from a melted-cheese dish of Chihuahua in northern Mexico.'),
((SELECT id FROM dishes WHERE slug='queso-dip'), 3, 'Plenty of kitchens make it by melting a block of processed cheese and stirring in chilies.'),
((SELECT id FROM dishes WHERE slug='queso-dip'), 4, 'You melt cheese with cream over low heat and stir in chopped green chilies and tomato until smooth.'),
((SELECT id FROM dishes WHERE slug='queso-dip'), 5, 'Tex-Mex melted cheese, warm and runny, scooped up with tortilla chips across the American Southwest.'),
((SELECT id FROM dishes WHERE slug='sopapillas'), 1, 'Hollow fried pillows that come with a squeeze bottle of honey.'),
((SELECT id FROM dishes WHERE slug='sopapillas'), 2, 'The name is a diminutive of a word that came into Spanish from Mozarabic, the old Romance of Moorish Spain.'),
((SELECT id FROM dishes WHERE slug='sopapillas'), 3, 'Diners tear off a corner and pour honey inside, or use them as bread to mop up red or green chile.'),
((SELECT id FROM dishes WHERE slug='sopapillas'), 4, 'You roll a lard-rich dough thin, cut it into squares, and fry them until they puff into hollow pockets.'),
((SELECT id FROM dishes WHERE slug='sopapillas'), 5, 'A puffy fried bread drizzled with honey, served with New Mexican plates in the American Southwest.'),
((SELECT id FROM dishes WHERE slug='breakfast-tacos'), 1, 'Bought two at a time in foil from a gas station counter at dawn.'),
((SELECT id FROM dishes WHERE slug='breakfast-tacos'), 2, 'Austin has claimed to be its home, and a writer answered that San Antonio never needed to brag about it.'),
((SELECT id FROM dishes WHERE slug='breakfast-tacos'), 3, 'Flour beats corn here: the tortilla is soft, warm, and folded around scrambled egg.'),
((SELECT id FROM dishes WHERE slug='breakfast-tacos'), 4, 'You scramble eggs with chorizo or potato, add cheese, and fold it into a warm flour tortilla with salsa.'),
((SELECT id FROM dishes WHERE slug='breakfast-tacos'), 5, 'Egg and chorizo in warm flour tortillas, the morning order of Texas and the American Southwest.'),
((SELECT id FROM dishes WHERE slug='chicken-marsala'), 1, 'Thin cutlets in a glossy brown pan sauce at a red-sauce joint.'),
((SELECT id FROM dishes WHERE slug='chicken-marsala'), 2, 'English families living in western Sicily in the 1800s may have started it, using the local fortified wine.'),
((SELECT id FROM dishes WHERE slug='chicken-marsala'), 3, 'Cooks boil the wine down to nearly a syrup in the same pan the cutlets fried in.'),
((SELECT id FROM dishes WHERE slug='chicken-marsala'), 4, 'You dredge pounded chicken breasts in flour, sauté them in butter, then add mushrooms and garlic to the pan.'),
((SELECT id FROM dishes WHERE slug='chicken-marsala'), 5, 'An Italian American cutlet dish in sweet wine and mushroom sauce, named for a Sicilian port.'),
((SELECT id FROM dishes WHERE slug='garlic-knots'), 1, 'The cheapest thing at the pizzeria, sometimes thrown in free.'),
((SELECT id FROM dishes WHERE slug='garlic-knots'), 2, 'Brooklyn pizzerias came up with them in the 1940s, and plenty of them claim to be first.'),
((SELECT id FROM dishes WHERE slug='garlic-knots'), 3, 'Pizzerias make them from leftover dough scraps, which is why they cost so little.'),
((SELECT id FROM dishes WHERE slug='garlic-knots'), 4, 'You tie ropes of dough into tight loops, bake them, brush them with garlic oil and parmesan, and bake again.'),
((SELECT id FROM dishes WHERE slug='garlic-knots'), 5, 'Italian American pizzeria twists of dough, glossy with garlic oil, with marinara for dipping.'),
((SELECT id FROM dishes WHERE slug='matzo-ball-soup'), 1, 'Golden broth with one big dumpling taking up most of the bowl.'),
((SELECT id FROM dishes WHERE slug='matzo-ball-soup'), 2, 'Ashkenazi cooks adapted the German bread dumpling, and an 1846 English cookbook printed the first recipe.'),
((SELECT id FROM dishes WHERE slug='matzo-ball-soup'), 3, 'Families argue floaters against sinkers, light enough to bob or dense enough to drop.'),
((SELECT id FROM dishes WHERE slug='matzo-ball-soup'), 4, 'You beat ground unleavened cracker meal with eggs and chicken fat, chill it, roll it, and simmer it in broth.'),
((SELECT id FROM dishes WHERE slug='matzo-ball-soup'), 5, 'A fluffy Passover dumpling in chicken soup with carrots and dill, from the American Jewish deli.'),
((SELECT id FROM dishes WHERE slug='pastrami-on-rye'), 1, 'A sandwich stacked so high you have to squash it to take a bite.'),
((SELECT id FROM dishes WHERE slug='pastrami-on-rye'), 2, 'Romanian Jews brought the cure to New York in the late 1800s, and one family claims a first sandwich in 1887.'),
((SELECT id FROM dishes WHERE slug='pastrami-on-rye'), 3, 'The meat is smoked and then steamed, which turns the connective tissue to gelatin so it falls apart.'),
((SELECT id FROM dishes WHERE slug='pastrami-on-rye'), 4, 'You brine beef navel, crust it with black pepper and coriander, smoke it, then steam it before slicing.'),
((SELECT id FROM dishes WHERE slug='pastrami-on-rye'), 5, 'Thin peppery slices of smoked beef piled on rye with yellow mustard, the American deli sandwich.'),
((SELECT id FROM dishes WHERE slug='knish'), 1, 'A heavy square of baked dough you eat from wax paper on the street.'),
((SELECT id FROM dishes WHERE slug='knish'), 2, 'Ashkenazi immigrants brought them over around 1900, and the first bakery for them opened in New York in 1910.'),
((SELECT id FROM dishes WHERE slug='knish'), 3, 'New York politicians posed eating them to show solidarity with Jewish working people.'),
((SELECT id FROM dishes WHERE slug='knish'), 4, 'You wrap a thin dough around seasoned mashed potato and onion, shape it square or round, and bake it.'),
((SELECT id FROM dishes WHERE slug='knish'), 5, 'A golden baked pocket of dense mashed potato, sold at American Jewish delis.'),
((SELECT id FROM dishes WHERE slug='babka'), 1, 'A twisted loaf that shows dark swirls when you slice it.'),
((SELECT id FROM dishes WHERE slug='babka'), 2, 'Jewish bakers in the early 1800s rolled spare challah dough with jam or cinnamon and baked it alongside.'),
((SELECT id FROM dishes WHERE slug='babka'), 3, 'A 1994 sitcom episode called cinnamon ''the lesser'' kind, ranking it behind chocolate.'),
((SELECT id FROM dishes WHERE slug='babka'), 4, 'You spread chocolate or cinnamon filling over rich yeast dough, roll it up, split it, and twist the halves together.'),
((SELECT id FROM dishes WHERE slug='babka'), 5, 'A braided chocolate swirl loaf from Polish Jewish bakers, its name meaning little grandmother.');
